import numpy as np
from scipy import stats
from sklearn.cluster import AgglomerativeClustering

MAX_DRIVERS = 5

def design(feats):
    # Check if no mechanism
    if np.random.rand() < 0.8:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Filter features with significant association (p < 0.05)
    sig_features = [fid for i, fid in enumerate(feats.ids) 
                   if feats.types[i] != 'clinical' or feats.types[i] == 'clinical' and np.abs(stats.ttest_ind(feats.x[:, feats.column(fid)][feats.y==1], 
                                                                                                           feats.x[:, feats.column(fid)][feats.y==0])[0]) > 2.0]

    # Remove near-duplicates (correlated pairs with |r| >= 0.6)
    corr_pairs = []
    for i, fid1 in enumerate(sig_features):
        for j, fid2 in enumerate(sig_features[i+1:], i+1):
            corr = np.corrcoef(feats.x[:, feats.column(fid1)], feats.x[:, feats.column(fid2)])[0,1]
            if abs(corr) >= 0.6:
                corr_pairs.append((fid1, fid2))

    # Cluster correlated features
    if corr_pairs:
        all_features = list(set([f for pair in corr_pairs for f in pair]))
        n_features = len(all_features)
        corr_matrix = np.ones((n_features, n_features))

        for i, fid1 in enumerate(all_features):
            for j, fid2 in enumerate(all_features):
                if i == j:
                    continue
                elif (fid1, fid2) in corr_pairs or (fid2, fid1) in corr_pairs:
                    corr_matrix[i,j] = np.corrcoef(feats.x[:, feats.column(fid1)], feats.x[:, feats.column(fid2)])[0,1]
                else:
                    corr_matrix[i,j] = 0

        clustering = AgglomerativeClustering(n_clusters=max(1, n_features//2), 
                                           affinity='precomputed', linkage='average')
        clusters = clustering.fit_predict(1 - np.abs(corr_matrix))

        # Select representative feature from each cluster
        selected_features = []
        for cluster_id in set(clusters):
            cluster_features = [all_features[i] for i in range(len(all_features)) if clusters[i] == cluster_id]
            # Prefer expression over copy_number over derived
            priority_order = {'expression': 0, 'copy_number': 1, 'derived': 2, 'clinical': 3}
            best_feature = min(cluster_features, key=lambda x: priority_order[feats.types[feats.ids.index(x)]])
            selected_features.append(best_feature)
    else:
        selected_features = sig_features

    # Rank by effect size (mean_y1 - mean_y0)
    def effect_size(fid):
        col_idx = feats.column(fid)
        y0_vals = feats.x[:, col_idx][feats.y == 0]
        y1_vals = feats.x[:, col_idx][feats.y == 1]
        return np.mean(y1_vals) - np.mean(y0_vals)

    selected_features.sort(key=effect_size, reverse=True)

    # Select top drivers
    drivers = tuple(selected_features[:MAX_DRIVERS])

    # All features used in model
    columns = tuple(selected_features)

    # No products
    products = ()

    # Loadings based on standardized coefficients (simplified)
    loadings = {fid: effect_size(fid) for fid in selected_features}

    return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)

